SELECT id,code FROM (SELECT h.assertion_id AS id,CASE WHEN (SELECT count(*) FROM assertion_vertex_subject WHERE assertion_id=h.assertion_id) + (SELECT count(*) FROM assertion_edge_subject WHERE assertion_id=h.assertion_id) <> 1 THEN 77 WHEN EXISTS (SELECT 1 FROM (SELECT * FROM assertion_vertex_subject WHERE assertion_id=h.assertion_id OFFSET 0) s CROSS JOIN LATERAL (SELECT * FROM edge WHERE id=s.subject_edge_id OFFSET 0) e JOIN entity k ON k.id=e.entity_id WHERE s.assertion_id=h.assertion_id AND (e.from_node<>h.assertion_id OR k.name<>'system.assertion-subject')) THEN 80 WHEN NOT EXISTS (SELECT 1 FROM (SELECT entity_id FROM node WHERE id=h.assertion_id OFFSET 0) n JOIN entity k ON k.id=n.entity_id WHERE k.name='system.assertion') THEN 83 WHEN (SELECT count(*) FROM (SELECT * FROM edge WHERE from_node=h.assertion_id OFFSET 0) e JOIN entity k ON k.id=e.entity_id WHERE e.from_node=h.assertion_id AND k.name='system.assertion-source') <> 1
        OR (SELECT count(*) FROM (SELECT * FROM edge WHERE from_node=h.assertion_id OFFSET 0) e JOIN entity k ON k.id=e.entity_id WHERE e.from_node=h.assertion_id AND k.name='system.assertion-author') <> 1
        OR (SELECT count(*) FROM (SELECT * FROM edge WHERE from_node=h.assertion_id OFFSET 0) e JOIN entity k ON k.id=e.entity_id WHERE e.from_node=h.assertion_id AND k.name='system.assertion-operation') < 1 THEN 88 WHEN EXISTS (SELECT 1 FROM (SELECT * FROM edge WHERE from_node=h.assertion_id OFFSET 0) e JOIN entity k ON k.id=e.entity_id CROSS JOIN LATERAL (SELECT entity_id FROM node WHERE id=e.to_node OFFSET 0) target JOIN entity tk ON tk.id=target.entity_id
        WHERE e.from_node=h.assertion_id AND ((k.name='system.assertion-source' AND tk.name NOT IN ('source','person','plugin','agent','agent-session'))
          OR (k.name='system.assertion-author' AND tk.name NOT IN ('source','person','plugin','agent','agent-session'))
          OR (k.name='system.assertion-operation' AND tk.name<>'system.operation')
          OR (k.name='system.assertion-unit' AND tk.name<>'system.unit'))) THEN 106 ELSE 0 END AS code FROM (SELECT * FROM assertion WHERE assertion_id>=$1 OFFSET 0) h) failures WHERE code<>0 ORDER BY id,code LIMIT 1;